// The scoring rules. Edit the points and lists here; nothing else needs to change.
return [{ json: {
  fit: {
    employees: [ { min: 200, points: 25 }, { min: 50, points: 15 }, { min: 10, points: 5 } ],
    industries: { points: 15, values: ['Software', 'Financial services', 'Logistics', 'Retail'] },
    countries: { points: 10, values: ['DE', 'AT', 'CH', 'NL', 'ES', 'GB'] },
    seniority: { points: 15, keywords: ['head', 'director', 'vp', 'chief', 'founder', 'lead'] },
  },
  engagement: {
    demoRequested: 20,
    websiteVisits: { pointsEach: 1, max: 10 },
    emailClicks: { pointsEach: 2, max: 10 },
  },
  tiers: { A: 70, B: 40 },
} }];

// Score every lead with the rules and keep the reasons, so a sales rep can see why.
const R = $('Scoring rules (edit me)').first().json;
const leads = $('Read the CSV').all().map(i => i.json);
const required = ['lead_id', 'company', 'industry', 'employees', 'country', 'job_title', 'website_visits_30d', 'email_clicks_30d', 'requested_demo'];
const missing = required.filter(c => !(c in (leads[0] ?? {})));
if (!leads.length || missing.length) {
  throw new Error('The CSV is missing columns: ' + (missing.join(', ') || 'no rows found'));
}

return leads.map(l => {
  const reasons = [];
  let score = 0;
  const add = (points, why) => { if (points) { score += points; reasons.push(`${why} +${points}`); } };

  const emp = Number(l.employees) || 0;
  const band = R.fit.employees.find(b => emp >= b.min);
  if (band) add(band.points, `${band.min}+ employees`);
  if (R.fit.industries.values.includes(l.industry)) add(R.fit.industries.points, l.industry);
  if (R.fit.countries.values.includes(l.country)) add(R.fit.countries.points, `market ${l.country}`);
  const title = String(l.job_title).toLowerCase();
  if (R.fit.seniority.keywords.some(k => title.split(/\W+/).includes(k))) add(R.fit.seniority.points, 'senior buyer');
  if (String(l.requested_demo).toLowerCase() === 'yes') add(R.engagement.demoRequested, 'requested a demo');
  add(Math.min(R.engagement.websiteVisits.max, (Number(l.website_visits_30d) || 0) * R.engagement.websiteVisits.pointsEach), 'site visits');
  add(Math.min(R.engagement.emailClicks.max, (Number(l.email_clicks_30d) || 0) * R.engagement.emailClicks.pointsEach), 'email clicks');

  score = Math.min(100, score);
  const tier = score >= R.tiers.A ? 'A' : score >= R.tiers.B ? 'B' : 'C';
  const outcome = String(l.converted ?? '').toLowerCase();
  return { json: {
    lead_id: String(l.lead_id), company: String(l.company), score, tier,
    reasons: reasons.join('; '),
    known_outcome: ['yes', 'no'].includes(outcome) ? outcome : '',
  } };
});

// Backtest: do higher tiers convert more often than the average lead?
const scored = $input.all().map(i => i.json);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const runId = 'run-' + String($execution.id).padStart(4, '0');
const known = scored.filter(l => l.known_outcome);
const pct = x => (Math.round(x * 1000) / 10) + '%';

let verdict, tableHtml = '';
if (!known.length) {
  verdict = 'No outcomes in the file, so no backtest. Scores are saved as a shadow run only.';
} else {
  const base = known.filter(l => l.known_outcome === 'yes').length / known.length;
  const rows = ['A', 'B', 'C'].map(t => {
    const inTier = known.filter(l => l.tier === t);
    const won = inTier.filter(l => l.known_outcome === 'yes').length;
    const rate = inTier.length ? won / inTier.length : 0;
    return { t, n: inTier.length, won, rate, lift: base ? rate / base : 0 };
  });
  const [a, b, c] = rows;
  const ordered = a.rate >= b.rate && b.rate >= c.rate;
  const ready = ordered && a.lift >= 2 && a.n >= 5;
  verdict = ready
    ? `Tier A converts at ${a.lift.toFixed(1)} times the average. The rules are ready for a shadow run next to the CRM.`
    : `The tiers do not separate well enough yet (tier A lift ${a.lift.toFixed(1)}, needs 2.0 with tiers in order). Adjust the rules before going live.`;
  tableHtml = `<table border="1" cellpadding="6" style="border-collapse:collapse">
<tr><th>Tier</th><th>Leads</th><th>Converted</th><th>Rate</th><th>Lift vs average</th></tr>
${rows.map(r => `<tr><td>${r.t}</td><td>${r.n}</td><td>${r.won}</td><td>${pct(r.rate)}</td><td>${r.lift.toFixed(1)}</td></tr>`).join('')}
<tr><td>All</td><td>${known.length}</td><td>${known.filter(l => l.known_outcome === 'yes').length}</td><td>${pct(base)}</td><td>1.0</td></tr></table>`;
}

const top = [...scored].sort((x, y) => y.score - x.score).slice(0, 5);
const summaryHtml = `
<h2>Lead scoring, ${esc(runId)}</h2>
<p>${scored.length} leads scored and saved to the lead_scores data table as a shadow run. Nothing was written to a CRM.</p>
<h3>Backtest</h3>
${tableHtml}
<p><b>${esc(verdict)}</b></p>
<h3>Top five</h3>
<ul>${top.map(l => `<li><b>${esc(l.company)}</b> (${esc(l.lead_id)}), score ${l.score}, tier ${l.tier}: ${esc(l.reasons)}</li>`).join('')}</ul>`;

return [{ json: { runId, verdict, summaryHtml } }];

// One row per lead, tagged with the run, ready for the data table.
const runId = $('Backtest').first().json.runId;
const scoredAt = new Date().toISOString();
return $('Score each lead').all().map(i => ({ json: { run_id: runId, scored_at: scoredAt, mode: 'shadow', ...i.json } }));
